def log_event(level, msg):
    event_log.append({"ts": datetime.now().strftime("%H:%M:%S"), "level": level, "msg": msg})
    if len(event_log) > 300:
        del event_log[0]

def risk_tier(level):
    if level >= TIER_THRESHOLDS["red"]:
        return "red"
    if level >= TIER_THRESHOLDS["orange"]:
        return "orange"
    if level >= TIER_THRESHOLDS["yellow"]:
        return "yellow"
    return "none"

NODE_SEED = {"node1": 1, "node2": 13}

def synth_reading(node_id, tick_offset=0):
    seed = NODE_SEED.get(node_id, 1)
    t = (datetime.now().timestamp() / 3.0) - tick_offset + seed
    wobble = (math.sin(t * 0.6) + 1) / 2
    tier = _forced_tier.get(node_id, "none")
    ranges = {"none": (0.1, 0.4), "yellow": (0.5, 0.9), "orange": (1.0, 1.7), "red": (1.8, 2.5)}
    lo, hi = ranges.get(tier, (0.1, 0.4))
    level = round(lo + wobble * (hi - lo), 2)
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return {
        "water_level": level,
        "water_flow": round(0.5 + wobble * 0.8, 2),
        "rainfall": round(wobble * 15.0, 1),
        "temperature": round(28.0 + wobble * 3.0, 1),
        "humidity": round(70.0 + wobble * 20.0, 1),
        "tier": risk_tier(level),
        "timestamp": now
    }

def node_history(node_id):
    readings = [synth_reading(node_id, tick_offset=i) for i in range(HISTORY_LEN - 1, -1, -1)]
    return {
        "water_level": [r["water_level"] for r in readings],
        "water_flow": [r["water_flow"] for r in readings],
        "rainfall": [r["rainfall"] for r in readings],
        "temperature": [r["temperature"] for r in readings],
        "humidity": [r["humidity"] for r in readings],
    }

def node_history_times_fmt(node_id):
    now = datetime.now()
    return [(now - timedelta(seconds=i * 3)).strftime("%H:%M:%S") for i in range(HISTORY_LEN - 1, -1, -1)]

def eta_minutes_to_red(node_id):
    levels = node_history(node_id)["water_level"]
    if len(levels) < 4:
        return None
    recent = levels[-4:]
    diffs = [recent[i + 1] - recent[i] for i in range(len(recent) - 1)]
    avg_rate = sum(diffs) / len(diffs)
    current = levels[-1]
    threshold = TIER_THRESHOLDS["red"]
    if current >= threshold:
        return 0
    if avg_rate <= 0.001:
        return None
    remaining = threshold - current
    seconds_needed = (remaining / avg_rate) * 3
    return round(seconds_needed / 60, 1)

def ai_confidence_for(tier):
    seed = (int(datetime.now().timestamp()) // 3) % 100
    if tier in ("none", "red"):
        return round(87 + (seed % 12), 1)
    return round(58 + (seed % 23), 1)

def current_node_status():
    status = {}
    for nid in NODE_ORDER:
        if nid in _real_overrides:
            status[nid] = _real_overrides[nid]
        else:
            status[nid] = synth_reading(nid)
    return status

def synth_hw(dev_id):
    dev = dict(HARDWARE[dev_id])
    forced = _forced_hw[dev_id]
    t = datetime.now().timestamp() / 5.0
    wobble = (math.sin(t + hash(dev_id) % 7) + 1) / 2
    dev["status"] = forced if forced else "online"
    if dev["kind"] == "esp":
        dev["battery_pct"] = round(max(4.0, dev["battery_pct"] - wobble * 2), 1)
        dev["latency_ms"] = round(20 + wobble * 40, 1)
    else:
        dev["cpu_pct"] = round(20 + wobble * 40, 1)
        dev["mem_pct"] = round(35 + wobble * 30, 1)
        dev["latency_ms"] = round(1 + wobble * 3, 1)
    dev["last_heartbeat"] = datetime.now().strftime("%H:%M:%S") if dev["status"] != "offline" else "—"
    return dev

def current_hardware():
    return {dev_id: synth_hw(dev_id) for dev_id in HARDWARE}

def synth_rain():
    t = datetime.now().timestamp() / 7.0
    wobble = (math.sin(t) + 1) / 2
    intensity = round(wobble * 22, 1)
    return {"intensity": intensity, "today_total": round(intensity * 3.2, 1),
            "timestamp": datetime.now().strftime("%H:%M:%S")}

def synth_alerts(status):
    alerts = []
    for nid, s in status.items():
        tier = s.get("tier", "none")
        if tier in ["orange", "red"]:
            alerts.append({
                "text": f"Warning: {NODE_META[nid]['label']} is at {tier.upper()} risk!",
                "time": s.get("timestamp", datetime.now().strftime("%H:%M:%S")),
                "color": TIER_COLOR.get(tier, "#e14b4b")
            })
    return alerts

def compute_ai_prediction(status_dict):
    active_tier = "none"
    max_level = 0.0
    for nid in NODE_ORDER:
        if nid in status_dict:
            lvl = status_dict[nid]["water_level"]
            if lvl > max_level:
                max_level = lvl
                active_tier = risk_tier(lvl)

    score_map = {"none": 15, "yellow": 45, "orange": 70, "red": 90}
    label_map = {"none": "All Clear", "yellow": "Moderate Risk", "orange": "High Alert", "red": "Critical Risk"}
    
    return {
        "risk_score": score_map.get(active_tier, 15),
        "label": label_map.get(active_tier, "All Clear"),
        "narrative": f"Current system activity is steady with active risk index evaluated as {active_tier}."
    }

