import json as _json

def build_api_payload():
    status = current_node_status()
    tiers = {nid: risk_tier(status[nid]["water_level"]) for nid in ALL_TABS}
    hist_out = {nid: node_history(nid) for nid in ALL_TABS}
    hist_times_out = {nid: node_history_times_fmt(nid) for nid in ALL_TABS}
    eta_out = {nid: eta_minutes_to_red(nid) for nid in ALL_TABS}
    
    return {
        "status": status,
        "tier": tiers,
        "tier_color": TIER_COLOR,
        "history": hist_out,
        "history_times": hist_times_out,
        "eta": eta_out,
        "data_source": data_source,
        "prediction": compute_ai_prediction(status),
        "alerts": synth_alerts(status)
    }

@app.route('/')
def dashboard():
    active = request.args.get('node', 'node1')
    if active not in ALL_TABS:
        active = 'node1'
    status = current_node_status()
    tiers = {nid: risk_tier(status[nid]["water_level"]) for nid in NODE_ORDER}
    tier_color_by_node = {nid: TIER_COLOR[tiers[nid]] for nid in NODE_ORDER}
    
    return render_template_string(
        DASHBOARD_HTML,
        status=status,
        active=active,
        meta=ALL_META,
        hq=HQ_META,
        node_order=NODE_ORDER,
        tabs=ALL_TABS,
        tier_color=tier_color_by_node,
        reports=resident_reports,
        alerts=synth_alerts(status),
        prediction=compute_ai_prediction(status),
        data_source=data_source,
        meta_json=_json.dumps(ALL_META),
        logo_b64=LOGO_B64
    )

@app.route('/api/status')
def api_status():
    return jsonify(build_api_payload())

@app.route('/resident')
def resident_portal():
    return render_template_string(RESIDENT_HTML, meta=NODE_META, node_order=NODE_ORDER)

@app.route('/controls')
def presenter_controls():
    return render_template_string(CONTROLS_HTML)

@app.route('/manifest.webmanifest')
def manifest():
    return jsonify({
        "name": "APAW Flood Defense — Command Center",
        "short_name": "APAW",
        "start_url": "/",
        "display": "standalone",
        "background_color": "#f2f4f7",
        "theme_color": "#0f1b2d"
    })

@app.route('/upload', methods=['POST'])
def upload_report():
    if 'photo' in request.files:
        file = request.files['photo']
        node = request.form.get('node', '')
        if file.filename != '':
            image_b64 = base64.b64encode(file.read()).decode('utf-8')
            report_id = len(resident_reports) + 1
            resident_reports.append({
                "id": report_id, "image_data": image_b64, "node": node,
                "time": datetime.now().strftime("%H:%M:%S"), "status": "Pending"
            })
    return redirect(url_for('resident_portal'))

@app.route('/set_mode/<mode_type>')
def set_mode(mode_type):
    global SIMULATION_MODE
    if mode_type in ['normal', 'moderate', 'storm']:
        SIMULATION_MODE = mode_type
        if mode_type == "normal":
            _forced_tier["node1"] = "none"
            _forced_tier["node2"] = "none"
        elif mode_type == "moderate":
            _forced_tier["node1"] = "yellow"
            _forced_tier["node2"] = "orange"
        elif mode_type == "storm":
            _forced_tier["node1"] = "red"
            _forced_tier["node2"] = "red"
    return redirect(url_for('dashboard'))

@app.route('/webhook/lorawan', methods=['POST'])
def lorawan_webhook():
    import time as _time
    payload = request.get_json(silent=True)
    if not payload:
        return jsonify({"ok": False, "error": "expected JSON body"}), 400
    node_id = payload.get("node_id")
    if not node_id or node_id not in NODE_ORDER:
        return jsonify({"ok": False, "error": "missing/unknown node_id"}), 400
    base = synth_reading(node_id)
    reading = dict(base)
    for k in METRICS:
        if k in payload:
            reading[k] = round(float(payload[k]), 2)
    reading["timestamp"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    _real_overrides[node_id] = reading
    _last_real_update[node_id] = _time.time()
    data_source[node_id] = "lorawan-live"
    return jsonify({"ok": True, "node_id": node_id, "applied": reading})

@app.route('/api/system')
def system_stats():
    return jsonify({
        "cpu_percent": None, 
        "memory_percent": None, 
        "memory_used_mb": None,
        "memory_total_mb": None, 
        "note": "Running in serverless environment."
    })

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=5000, debug=False)